#include <ztest.h>
#include <kernel_internal.h>

#define STACK_SIZE (4 + Z_TEST_STACK_SIZE_ADJUSTMENT)

static K_STACK_DEFINE(stack, STACK_SIZE);
static stack_data_t data[STACK_SIZE];

/**
 * @brief Test k_stack_pop() on an empty stack
 * @ingroup kernel_stack_tests
 * @see k_stack_init(), k_stack_pop()
 */
static void test_stack_pop_fail(void)
{
	stack_data_t data_tmp;

	/* setup */
	k_stack_init(&stack, (stack_data_t *)data, STACK_SIZE);

	/* pop from an empty stack */
	zassert_equal(k_stack_pop(&stack, &data_tmp, K_NO_WAIT), -EAGAIN,
		      "stack_pop should fail");
}

/**
 * @brief Test k_stack_push() on a full stack
 *
 * @details Fill a stack to full, and then push one more data to it.
 * The test will fail if the push is successful.
 *
 * @ingroup kernel_stack_tests
 *
 * @see k_stack_init(), k_stack_push()
 */
static void test_stack_push_full(void)
{
	stack_data_t data_tmp;
	int i;

	/* setup */
	k_stack_init(&stack, (stack_data_t *)data, STACK_SIZE);

	/* fill the stack */
	for (i = 0; i < STACK_SIZE; i++) {
		k_stack_push(&stack, (stack_data_t)i);
	}

	/* push to a full stack */
	zassert_equal(k_stack_push(&stack, data_tmp), -ENOMEM,
		      "stack_push should fail");

	/* cleanup */
	for (i = 0; i < STACK_SIZE; i++) {
		k_stack_pop(&stack, &data_tmp, K_NO_WAIT);
	}
}

/*
 * @brief Test k_stack_cleanup() with pending threads
 * @details Create a thread that pends on an empty stack.
 * Then, call k_stack_cleanup() and check if it returns an error.
 * @ingroup kernel_stack_tests
 * @see k_stack_cleanup()
 */
#define THREAD_STACK_SIZE (512 + Z_TEST_STACK_SIZE_ADJUSTMENT)
static K_THREAD_STACK_DEFINE(tstack, THREAD_STACK_SIZE);
static struct k_thread tdata;

static void tstack_cleanup(void *p1, void *p2, void *p3)
{
	stack_data_t data_tmp;

	zassert_false(k_stack_pop((struct k_stack *)p1, &data_tmp, K_FOREVER),
		      "thread is not blocked");
}

static void test_stack_cleanup_error(void)
{
	k_tid_t tid;

	/* setup */
	k_stack_init(&stack, (stack_data_t *)data, STACK_SIZE);

	/* create a thread that pend on the stack */
	tid = k_thread_create(&tdata, tstack, THREAD_STACK_SIZE,
			      tstack_cleanup, &stack, NULL, NULL,
			      K_PRIO_PREEMPT(1), 0, K_NO_WAIT);

	/* Let the thread run and pend on the stack */
	k_sleep(K_MSEC(100));

	/* k_stack_cleanup should fail as there is a pending thread */
	zassert_equal(k_stack_cleanup(&stack), -EAGAIN,
		      "k_stack_cleanup should fail");

	/* cleanup */
	k_thread_abort(tid);
}

/*test case main entry*/
void test_main(void)
{
	k_thread_access_grant(k_current_get(), &stack, &tdata, &tstack);

	ztest_test_suite(stack_fail,
			 ztest_user_unit_test(test_stack_pop_fail),
			 ztest_user_unit_test(test_stack_push_full),
			 ztest_user_unit_test(test_stack_cleanup_error));
	ztest_run_test_suite(stack_fail);
}
